sys_security_acl.script:
(function executeRule(current, previous /*null when async*/) {

    // Admin full access
    if (gs.hasRole('x_1917769_servicen.admin')) {
        return true;
    }

    var userID = gs.getUserID();

    // Get employee record of logged-in user
    var emp = new GlideRecord('u_employee');
    emp.addQuery('user', userID);
    emp.query();

    if (!emp.next()) {
        return false;
    }

    // Branch Manager → same branch
    if (gs.hasRole('x_1917769_servicen.branch_manager')) {
        return current.branch == emp.branch;
    }

    // Facility Admin → only assigned facilities
    if (gs.hasRole('x_1917769_servicen.facility_admin')) {
        return current.facility_admin == userID;
    }

    // Employee → same branch facilities only
    if (gs.hasRole('x_1917769_servicen.employee_user')) {
        return current.branch == emp.branch && current.active == true;
    }

    return false;

})(current, previous);
